import { cva, type VariantProps } from "class-variance-authority";
import { Slot } from "radix-ui";
import type * as React from "react";
import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "inline-flex shrink-0 items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap transition-all outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        destructive:
          "bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20",
        outline: "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground",
        secondary: "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost: "hover:bg-accent hover:text-accent-foreground",
        link: "text-primary underline-offset-4 hover:underline",
        toolbar:
          "toolbar-action control rounded-[var(--control-radius)] text-[0.66rem] font-semibold tracking-[0.5px] uppercase",
        dialog: "control rounded-[var(--control-radius)] text-[0.8rem]",
        "dialog-primary": "control rounded-[var(--control-radius)] control-primary text-[0.8rem]",
        "dialog-danger":
          "control rounded-[var(--control-radius)] control-primary text-[0.8rem] bg-[var(--danger-fill)] border-[var(--danger)] hover:bg-[var(--delete-btn-hover)]",
        "toolbar-primary":
          "toolbar-action toolbar-action-primary control rounded-[var(--control-radius)] control-primary text-[0.66rem] font-semibold tracking-[0.5px] uppercase",
        "toolbar-danger":
          "toolbar-action toolbar-action-danger control rounded-[var(--control-radius)] control-danger text-[0.66rem] font-semibold tracking-[0.5px] uppercase",
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        xs: "h-6 gap-1 rounded-md px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
        "icon-xs": "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
        "icon-sm": "size-8",
        "icon-lg": "size-10",
        toolbar: "h-[30px] gap-[7px] px-3 py-0",
        dialog: "h-auto min-w-[72px] px-3 py-[5px] leading-[normal]",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean;
  }) {
  const Comp = asChild ? Slot.Root : "button";

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  );
}

export { Button, buttonVariants };
